function formatDocument(value: string): string {
  const digits = value.replace(/\D/g, "");
  if (digits.length === 11) return digits.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");
  if (digits.length === 14) return digits.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, "$1.$2.$3/$4-$5");
  return value;
}
function formatPhone(value: string): string {
  const digits = value.replace(/\D/g, "");
  const countryPrefix = digits.startsWith("55") && (digits.length === 12 || digits.length === 13) ? "+55 " : "";
  const local = countryPrefix ? digits.slice(2) : digits;
  if (local.length === 11) return `${countryPrefix}(${local.slice(0, 2)}) ${local[2]}${local.slice(3, 7)}-${local.slice(7)}`;
  if (local.length === 10) return `${countryPrefix}(${local.slice(0, 2)}) ${local.slice(2, 6)}-${local.slice(6)}`;
  return value;
}
function displayValue(value: unknown, key: string): string { if (value == null) return "—"; if (key === "endereco" && typeof value === "object") return String((value as {formatted?:string}).formatted ?? "—"); if ((key === "cpf_cnpj" || key === "cnpj") && typeof value === "string") return formatDocument(value); if ((key === "fone" || key === "celular") && typeof value === "string") return formatPhone(value); if (key === "status") return value === "ativo" ? "Ativo" : "Inativo"; if (key === "categoria") return String(value).replaceAll("_", " ").toLocaleUpperCase("pt-BR"); if (key === "comissao_camarote" || key === "imposto") return `${value}%`; return String(value); }
